std::string image_word_hex(const std::bitset<256>& bits) {
    std::string out(64,'0');
    for(int i=0;i<64;++i) {
        unsigned v=0; for(int b=0;b<4;++b) if(bits[4*i+b]) v|=1u<<b;
        out[63-i]="0123456789abcdef"[v];
    }
    return out;
}
std::bitset<256> image_word_from_hex(const std::string& text) {
    if(text.size()!=64)throw std::runtime_error("word length");
    std::bitset<256> out;
    for(int i=0;i<64;++i) {
        char c=text[63-i];
        if(!((c>='0'&&c<='9')||(c>='a'&&c<='f')))throw std::runtime_error("word hex");
        unsigned v=c<='9'?c-'0':c-'a'+10;
        for(int b=0;b<4;++b)out[4*i+b]=(v>>b)&1;
    }
    return out;
}

namespace {
using namespace scamp;
struct InvalidImage {};
void require(bool ok) {if(!ok)throw InvalidImage();}
unsigned popcount(uint64_t v) {return unsigned(__builtin_popcountll(v));}
uint64_t field(const std::bitset<256>& w,unsigned start,unsigned n) {
    uint64_t v=0;
    for(unsigned i=0;i<n;++i)if(w[start+i])v|=uint64_t(1)<<i;
    return v;
}
bool zero(const std::bitset<256>& w,unsigned begin,unsigned end) {
    for(unsigned i=begin;i<end;++i)if(w[i])return false;
    return true;
}
struct Child {unsigned key;ImageLoc loc;bool bulk;};
struct Marker {ip6_t region;unsigned depth;uint32_t hop;};

class Validator {
    const ImageData& d;
    std::array<std::vector<unsigned char>,RAM_NUM> used;
    std::vector<unsigned char> used_patterns,used_ni;
    PrefixTable fib;
    std::vector<Marker> markers;
    unsigned route_count=0;

    void add_prefix(ip6_t ip,unsigned len,unsigned origin,unsigned maxlen,uint32_t hop) {
        require(len<=maxlen && (origin==0 || len>origin) && hop<null_hop);
        require(++route_count<=8192);
        require(fib.insert(ip,len,hop));
    }
    std::vector<Child> explicit_children(const std::bitset<256>& w,unsigned off,
                                          unsigned count,int parent) {
        std::vector<Child> out;
        bool absent=false;int last=-1;
        for(unsigned i=0;i<count;++i) {
            uint32_t raw=uint32_t(field(w,off+32*i,32));
            if(raw==(15u<<6)) {absent=true;continue;}
            unsigned key=raw&63, stage=(raw>>6)&15,cell=raw>>10;
            require(!absent && int(key)>last && stage<=10 && int(stage)<parent && cell<131072);
            last=int(key);out.push_back({key,{int(stage),cell},false});
        }
        return out;
    }
    unsigned walk(ImageLoc loc,unsigned origin,unsigned maxlen,ip6_t region,
                  unsigned depth,bool bulk=false) {
        require(loc.stage>=0 && loc.stage<RAM_NUM && loc.cell<d.cells[loc.stage] && depth<=maxlen);
        const auto& w=d.banks[loc.stage][loc.cell/2];
        unsigned off=(loc.cell&1)*128;
        unsigned type=unsigned(field(w,off,3));
        require(type>=1 && type<=5);
        bool half=type==1||type==4;
        unsigned charge=(!half||bulk)?2:1;
        if(charge==2)require((loc.cell&1)==0);
        require(charge<=d.cells[loc.stage]-loc.cell);
        for(unsigned i=0;i<charge;++i) {
            require(!used[loc.stage][loc.cell+i]); used[loc.stage][loc.cell+i]=1;
        }
        if(half&&bulk)require(zero(w,128,256));
        uint32_t bmp=uint32_t(field(w,off+3,22));
        markers.push_back({region,depth,bmp});
        if(type==4||type==5) {
            unsigned count=type==4?1:2;
            for(unsigned i=0;i<count;++i) {
                unsigned at=off+25+94*i;
                uint64_t fragment=field(w,at,64);
                unsigned len=unsigned(field(w,at+64,8));
                uint32_t hop=uint32_t(field(w,at+72,22));
                require(len<=maxlen-origin && (origin==0 || len>=1));
                require(len+origin>=depth && (fragment&~mask64(len))==0);
                ip6_t p;
                if(origin==0)p={fragment,0};
                else if(origin==16)p={(region.hi&mask64(16))|(fragment>>16),0};
                else p={region.hi,fragment};
                require(matches(p,region,depth));
                add_prefix(p,origin+len,origin,maxlen,hop);
            }
            require(zero(w,off+(type==4?119:213),off+(half?128:256)));
            return count;
        }

        unsigned id=unsigned(field(w,off+25,16));
        unsigned base=unsigned(field(w,off+41,22));
        require(id<d.bitmaps.size()); used_patterns[id]=1;
        uint64_t pattern=d.bitmaps[id];
        unsigned count=popcount(pattern);
        if(count==0)require(base==0);
        require(base<=d.nexthops.size() && count<=d.nexthops.size()-base);
        unsigned ni=base;
        for(unsigned pos=1;pos<64;++pos)if(pattern&(uint64_t(1)<<pos)) {
            unsigned len=0; while((2u<<len)<=pos)++len;
            unsigned val=pos-(1u<<len);
            require(depth+len<=maxlen);
            ip6_t p=append(region,depth,len,val);
            require(!used_ni[ni]);used_ni[ni]=1;
            add_prefix(p,depth+len,origin,maxlen,d.nexthops[ni++]);
        }
        std::vector<Child> children;
        if(type==1||type==2) {
            children=explicit_children(w,off+63,type==1?2:6,loc.stage);
            require(type==1 ? children.size()<=2 : children.size()>=3 && children.size()<=6);
            require(zero(w,off+(type==1?127:255),off+(half?128:256)));
        } else {
            uint64_t bm=field(w,off+63,64);
            unsigned basecell=unsigned(field(w,off+127,22));
            unsigned stage=unsigned(field(w,off+149,4));
            require(popcount(bm)>=4 && stage<=10 && int(stage)<loc.stage && !(basecell&1));
            require(basecell<d.cells[stage] && 2*popcount(bm)<=d.cells[stage]-basecell);
            children=explicit_children(w,off+153,3,loc.stage);
            for(auto c:children)require(!(bm&(uint64_t(1)<<c.key)));
            unsigned rank=0;
            for(unsigned k=0;k<64;++k)if(bm&(uint64_t(1)<<k)) {
                children.push_back({k,{int(stage),basecell+2*rank++},true});
            }
            require(children.size()>=7 && children.size()<=64);
            require(zero(w,off+249,off+256));
        }
        if(!children.empty())require(depth+6<=maxlen);
        for(auto c:children) {
            ip6_t r=append(region,depth,6,c.key);
            count+=walk(c.loc,origin,maxlen,r,depth+6,c.bulk);
            require(count<=8192);
        }
        // One/two-route subtrees must be inline, even if a larger node could
        // encode the same lookup results.  No leaf pushing or redundancy loss.
        require(count>=3);
        return count;
    }
public:
    explicit Validator(const ImageData& data):d(data) {}
    void run() {
        require(d.front16.size()<=4096 && d.front64.size()<=4096 &&
                d.bitmaps.size()<=8193 && d.nexthops.size()<=8192);
        size_t rows=0;
        for(int s=0;s<RAM_NUM;++s) {
            require(d.cells[s]<=131072 && d.banks[s].size()==(d.cells[s]+1)/2);
            rows+=d.banks[s].size(); used[s].assign(d.cells[s],0);
            if(d.cells[s]&1)require(zero(d.banks[s].back(),128,256));
        }
        require(rows<=65536);
        for(size_t i=0;i<d.bitmaps.size();++i) {
            require(!(d.bitmaps[i]&1));
            if(i)require(d.bitmaps[i-1]<d.bitmaps[i]);
        }
        for(auto h:d.nexthops)require(h<null_hop);
        used_patterns.assign(d.bitmaps.size(),0);used_ni.assign(d.nexthops.size(),0);
        if(d.root.stage==-1)require(d.root.cell==0);
        else walk(d.root,0,16,{0,0},0);
        for(unsigned which=0;which<2;++which) {
            const auto& fronts=which?d.front64:d.front16;
            uint64_t last=0;bool first=true;
            for(auto f:fronts) {
                require((which||f.key<=65535) && (first||f.key>last));
                first=false;last=f.key;
                ip6_t region={which?f.key:f.key<<48,0};
                walk(f.loc,which?64:16,which?128:64,region,which?64:16);
            }
        }
        for(int s=0;s<RAM_NUM;++s)for(auto b:used[s])require(b);
        for(auto b:used_patterns)require(b);
        for(auto b:used_ni)require(b);
        // Global, equal-depth-inclusive BMPs are checked only after ALL
        // forests have contributed their owned prefixes.
        for(auto m:markers) require(m.hop==fib.lookup(m.region,m.depth));
    }
};

ImageLoc find_front(const std::vector<ImageFront>& fronts,uint64_t key) {
    auto it=std::lower_bound(fronts.begin(),fronts.end(),key,
        [](const ImageFront& f,uint64_t k){return f.key<k;});
    if(it!=fronts.end()&&it->key==key)return it->loc;
    return ImageLoc();
}
nexthop_t public_hop(uint32_t h) {return h==null_hop?LPM_INVALID_NH:h;}
}

bool MemoryImage::load(const ImageData& proposed) {
    try {
        Validator(proposed).run();
    } catch(const InvalidImage&) {return false;}
    // Copy into a temporary first.  No references to the caller's image or
    // live state survive the commit, and rejection leaves data_ untouched.
    ImageData next=proposed;
    std::swap(data_,next);
    return true;
}

nexthop_t MemoryImage::lookup(ip6_t ip) const {
    using namespace scamp;
    const ImageData& d=data_;
    unsigned origin=64,maxlen=128;
    ImageLoc at=find_front(d.front64,ip.hi);
    if(at.stage<0) {at=find_front(d.front16,ip.hi>>48);origin=16;maxlen=64;}
    if(at.stage<0) {at=d.root;origin=0;maxlen=16;}
    unsigned depth=origin;
    // The validator proved that every edge descends a stage and that all
    // fields below resolve; lookup reads only the committed serialized data.
    while(at.stage>=0) {
        const auto& w=d.banks[at.stage][at.cell/2];
        unsigned off=(at.cell&1)*128;
        unsigned type=unsigned(field(w,off,3));
        uint32_t result=uint32_t(field(w,off+3,22));
        if(type==4||type==5) {
            unsigned best=0;bool found=false;
            for(unsigned i=0;i<(type==4?1u:2u);++i) {
                unsigned p=off+25+94*i;
                uint64_t frag=field(w,p,64);unsigned len=unsigned(field(w,p+64,8));
                uint64_t input=origin==64?ip.lo:(origin==16?ip.hi<<16:ip.hi);
                if(((input^frag)&mask64(len))==0 && (!found||len>best)) {
                    found=true;best=len;result=uint32_t(field(w,p+72,22));
                }
            }
            return public_hop(result);
        }
        unsigned key=extract(ip,depth,6);
        ImageLoc child;
        unsigned lim=type==1?2:(type==2?6:3);
        unsigned start=off+(type==3?153:63);
        for(unsigned i=0;i<lim;++i) {
            uint32_t raw=uint32_t(field(w,start+32*i,32));
            if(raw!=(15u<<6) && (raw&63)==key)child={int((raw>>6)&15),raw>>10};
        }
        if(type==3) {
            uint64_t bm=field(w,off+63,64);
            if(bm&(uint64_t(1)<<key)) {
                uint64_t before=key?bm&((uint64_t(1)<<key)-1):0;
                child={int(field(w,off+149,4)),uint32_t(field(w,off+127,22)+2*popcount(before))};
            }
        }
        if(child.stage>=0) {at=child;depth+=6;continue;}
        uint64_t bm=d.bitmaps[field(w,off+25,16)];
        unsigned base=unsigned(field(w,off+41,22));
        for(int l=int(std::min(5u,maxlen-depth));l>=0;--l) {
            unsigned pos=(1u<<l)+extract(ip,depth,unsigned(l));
            if(bm&(uint64_t(1)<<pos)) {
                uint64_t before=bm&((uint64_t(1)<<pos)-1);
                return d.nexthops[base+popcount(before)];
            }
        }
        return public_hop(result);
    }
    return LPM_INVALID_NH;
}
